const stateTip = document.getElementById("stateTip");
let activePath = null;
mapEl.querySelectorAll(".state-path").forEach(function(p) {
  p.addEventListener("mouseenter", function() {
    if (activePath) activePath.classList.remove("is-active");
    activePath = p;
    p.classList.add("is-active");
    stateTip.textContent = p.getAttribute("data-name");
    stateTip.classList.add("is-visible");
  });
  p.addEventListener("mousemove", function(e) {
    const r = mapEl.parentElement.getBoundingClientRect();
    stateTip.style.left = e.clientX - r.left + "px";
    stateTip.style.top = e.clientY - r.top + "px";
  });
  p.addEventListener("mouseleave", function() {
    p.classList.remove("is-active");
    if (activePath === p) activePath = null;
    stateTip.classList.remove("is-visible");
  });
});
const track = document.getElementById("track");
const navLinks = Array.from(document.querySelectorAll(".nav-link"));
const indicator = document.getElementById("navIndicator");
const nav = document.getElementById("mainNav");
let current = 0;
function positionIndicator() {
  const el = navLinks[current];
  if (!el) {
    indicator.style.width = "0px";
    return;
  }
  const r = el.getBoundingClientRect();
  const nr = nav.getBoundingClientRect();
  indicator.style.width = r.width + "px";
  indicator.style.left = r.left - nr.left + "px";
}
function goTo(i) {
  if (i === current || i < 0 || i > 4) return;
  current = i;
  track.style.transform = `translateX(-${i * 20}%)`;
  navLinks.forEach((l, idx) => l.classList.toggle("active", idx === i));
  positionIndicator();
  const pages = document.querySelectorAll(".page");
  pages[i].scrollTop = 0;
}
document.querySelectorAll("[data-goto]").forEach((el) => {
  el.addEventListener("click", (e) => {
    e.preventDefault();
    goTo(parseInt(el.getAttribute("data-goto")));
  });
});
(function() {
  const btn = document.getElementById("loginBtn");
  const gate = document.getElementById("officialGate");
  if (!btn || !gate) return;
  const LOGIN_ICON = btn.querySelector("svg").outerHTML;
  const tok = () => {
    try {
      return sessionStorage.getItem("watercast_user");
    } catch (_) {
      return null;
    }
  };
  const who = () => {
    try {
      return sessionStorage.getItem("watercast_user") || "Staff";
    } catch (_) {
      return "Staff";
    }
  };
  function sync() {
    const on = !!tok();
    btn.classList.toggle("is-on", on);
    btn.innerHTML = LOGIN_ICON + (on ? who() + " · Logout" : "Login");
    btn.title = on ? "Sign out of official mode" : "";
    document.body.classList.toggle("is-admin", on);
  }
  window.wcSyncLoginBtn = sync;
  sync();
  const gt = gate.querySelector(".gate-text");
  gt.innerHTML = [...gt.textContent].map((ch, i) => `<span style="--i:${i}">${ch === " " ? "&nbsp;" : ch}</span>`).join("");
  let busy = false;
  btn.addEventListener("click", () => {
    if (tok()) {
      let csrf = "";
      try {
        csrf = sessionStorage.getItem("watercast_csrf") || "";
      } catch (_) {
      }
      const done = () => {
        try {
          ["watercast_csrf", "watercast_user", "watercast_geo", "watercast_manual_loc"].forEach((k) => sessionStorage.removeItem(k));
        } catch (_) {
        }
        window.location.reload();
      };
      fetch("/api/auth/logout", { method: "POST", credentials: "same-origin", headers: { "X-CSRF-Token": csrf } }).then(done, done);
      return;
    }
    if (busy) return;
    busy = true;
    gate.classList.add("show");
    requestAnimationFrame(() => requestAnimationFrame(() => gate.classList.add("in")));
    setTimeout(() => {
      window.location.href = "login";
    }, 2200);
  });
  window.addEventListener("pageshow", () => {
    busy = false;
    gate.classList.remove("in", "show");
    sync();
  });
})();
document.getElementById("brandLogo").addEventListener("click", () => {
  window.location.reload();
});
window.addEventListener("resize", positionIndicator);
window.addEventListener("load", positionIndicator);
setTimeout(positionIndicator, 60);
function wireToggleGroup(selector) {
  document.querySelectorAll(selector).forEach((group) => {
    group.addEventListener("click", () => {
      const g = group.getAttribute("data-group");
      document.querySelectorAll(`[data-group="${g}"]`).forEach((el) => el.classList.remove("active"));
      group.classList.add("active");
    });
  });
}
wireToggleGroup(".choice-pill");
wireToggleGroup(".urgency-btn");
document.querySelectorAll(".pill-row").forEach((row) => {
  row.querySelectorAll(".pill").forEach((p) => {
    p.addEventListener("click", () => {
      row.querySelectorAll(".pill").forEach((x) => {
        x.classList.remove("active");
      });
      p.classList.add("active");
    });
  });
});
document.querySelectorAll(".day-card").forEach((d) => {
  d.addEventListener("click", () => {
    document.querySelectorAll(".day-card").forEach((x) => x.classList.remove("active"));
    d.classList.add("active");
  });
});
